import java.io.*;import java.nio.charset.StandardCharsets;class TaskBinding{static String printed(String s){PrintStream oldOut=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream output=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(output);System.setErr(output);Reverse.print(s);}finally{System.setOut(oldOut);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8);}}
